[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "macbook-comparison-surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "macbook-comparison-surface",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "children": [
              "title_text",
              "assumptions_card",
              "summary_card",
              "comparison_card",
              "differences_card",
              "actions_card",
              "sources_card"
            ],
            "spacing": "medium"
          }
        },
        {
          "id": "title_text",
          "type": "Text",
          "properties": {
            "text": "MacBook Air M1 vs. M2 Comparison",
            "style": "title"
          }
        },
        {
          "id": "assumptions_card",
          "type": "Card",
          "properties": {
            "child": "assumptions_text"
          }
        },
        {
          "id": "assumptions_text",
          "type": "Text",
          "properties": {
            "text": "**Assumptions:** This comparison is based on the official technical specifications released by Apple for the standard configurations of both models. \"Base\" refers to the entry-level configuration, and \"Maximum\" refers to the highest build-to-order option available."
          }
        },
        {
          "id": "summary_card",
          "type": "Card",
          "properties": {
            "child": "summary_col"
          }
        },
        {
          "id": "summary_col",
          "type": "Column",
          "properties": {
            "children": [
              "summary_title",
              "summary_text"
            ]
          }
        },
        {
          "id": "summary_title",
          "type": "Text",
          "properties": {
            "text": "Summary",
            "style": "headline"
          }
        },
        {
          "id": "summary_text",
          "type": "Text",
          "properties": {
            "text": "The 2022 MacBook Air (M2) offers a significant upgrade over the 2020 M1 model, featuring a more powerful and efficient chip, a modern flat-edge design, a larger and brighter display, and expanded memory support. While the M1 model remains a powerful machine for everyday tasks, the M2 model provides notable performance gains, particularly in graphics-intensive applications, and introduces key quality-of-life improvements like MagSafe charging and a better webcam."
          }
        },
        {
          "id": "comparison_card",
          "type": "Card",
          "properties": {
            "child": "comparison_col"
          }
        },
        {
          "id": "comparison_col",
          "type": "Column",
          "properties": {
            "children": [
              "comparison_title",
              "comparison_table"
            ]
          }
        },
        {
          "id": "comparison_title",
          "type": "Text",
          "properties": {
            "text": "Comparison Table",
            "style": "headline"
          }
        },
        {
          "id": "comparison_table",
          "type": "Table",
          "properties": {
            "columns": [
              {
                "header": "Specification"
              },
              {
                "header": "2020 MacBook Air (M1)"
              },
              {
                "header": "2022 MacBook Air (M2)"
              }
            ],
            "rows": [
              {
                "cells": [
                  {
                    "child": "cell_cpu"
                  },
                  {
                    "child": "cell_cpu_m1"
                  },
                  {
                    "child": "cell_cpu_m2"
                  }
                ]
              },
              {
                "cells": [
                  {
                    "child": "cell_gpu"
                  },
                  {
                    "child": "cell_gpu_m1"
                  },
                  {
                    "child": "cell_gpu_m2"
                  }
                ]
              },
              {
                "cells": [
                  {
                    "child": "cell_mem"
                  },
                  {
                    "child": "cell_mem_m1"
                  },
                  {
                    "child": "cell_mem_m2"
                  }
                ]
              },
              {
                "cells": [
                  {
                    "child": "cell_weight"
                  },
                  {
                    "child": "cell_weight_m1"
                  },
                  {
                    "child": "cell_weight_m2"
                  }
                ]
              }
            ]
          }
        },
        {
          "id": "cell_cpu",
          "type": "Text",
          "properties": {
            "text": "CPU Cores (Base)"
          }
        },
        {
          "id": "cell_cpu_m1",
          "type": "Text",
          "properties": {
            "text": "8-core (4 performance, 4 efficiency)"
          }
        },
        {
          "id": "cell_cpu_m2",
          "type": "Text",
          "properties": {
            "text": "8-core (4 performance, 4 efficiency)"
          }
        },
        {
          "id": "cell_gpu",
          "type": "Text",
          "properties": {
            "text": "GPU Cores (Base)"
          }
        },
        {
          "id": "cell_gpu_m1",
          "type": "Text",
          "properties": {
            "text": "7-core"
          }
        },
        {
          "id": "cell_gpu_m2",
          "type": "Text",
          "properties": {
            "text": "8-core"
          }
        },
        {
          "id": "cell_mem",
          "type": "Text",
          "properties": {
            "text": "Maximum Unified Memory"
          }
        },
        {
          "id": "cell_mem_m1",
          "type": "Text",
          "properties": {
            "text": "16GB"
          }
        },
        {
          "id": "cell_mem_m2",
          "type": "Text",
          "properties": {
            "text": "24GB"
          }
        },
        {
          "id": "cell_weight",
          "type": "Text",
          "properties": {
            "text": "Weight"
          }
        },
        {
          "id": "cell_weight_m1",
          "type": "Text",
          "properties": {
            "text": "2.8 pounds (1.29 kg)"
          }
        },
        {
          "id": "cell_weight_m2",
          "type": "Text",
          "properties": {
            "text": "2.7 pounds (1.24 kg)"
          }
        },
        {
          "id": "differences_card",
          "type": "Card",
          "properties": {
            "child": "differences_col"
          }
        },
        {
          "id": "differences_col",
          "type": "Column",
          "properties": {
            "children": [
              "differences_title",
              "diff_1_col",
              "diff_2_col",
              "diff_3_col",
              "diff_4_col"
            ],
            "spacing": "medium"
          }
        },
        {
          "id": "differences_title",
          "type": "Text",
          "properties": {
            "text": "Key Differences Explained",
            "style": "headline"
          }
        },
        {
          "id": "diff_1_col",
          "type": "Column",
          "properties": {
            "children": [
              "diff_1_title",
              "diff_1_text"
            ]
          }
        },
        {
          "id": "diff_1_title",
          "type": "Text",
          "properties": {
            "text": "**Processor Performance**"
          }
        },
        {
          "id": "diff_1_text",
          "type": "Text",
          "properties": {
            "text": "The M2 chip delivers an 18% faster CPU, a 35% more powerful GPU, and a 40% faster Neural Engine compared to the M1. It also features increased memory bandwidth, which improves multitasking performance."
          }
        },
        {
          "id": "diff_2_col",
          "type": "Column",
          "properties": {
            "children": [
              "diff_2_title",
              "diff_2_text"
            ]
          }
        },
        {
          "id": "diff_2_title",
          "type": "Text",
          "properties": {
            "text": "**Design and Display**"
          }
        },
        {
          "id": "diff_2_text",
          "type": "Text",
          "properties": {
            "text": "The M2 Air has a completely new, uniform-thickness design and is slightly lighter. It boasts a larger 13.6-inch Liquid Retina display that is brighter (500 nits vs. 400 nits) and supports 1 billion colors. This display includes a notch for the camera. The M1 Air retains the classic tapered wedge design with a 13.3-inch Retina display."
          }
        },
        {
          "id": "diff_3_col",
          "type": "Column",
          "properties": {
            "children": [
              "diff_3_title",
              "diff_3_text"
            ]
          }
        },
        {
          "id": "diff_3_title",
          "type": "Text",
          "properties": {
            "text": "**Charging and Ports**"
          }
        },
        {
          "id": "diff_3_text",
          "type": "Text",
          "properties": {
            "text": "The M2 Air brings back the dedicated MagSafe 3 charging port, which frees up its two Thunderbolt / USB 4 ports for accessories even while charging. The M1 Air charges via one of its two Thunderbolt / USB 4 ports."
          }
        },
        {
          "id": "diff_4_col",
          "type": "Column",
          "properties": {
            "children": [
              "diff_4_title",
              "diff_4_text"
            ]
          }
        },
        {
          "id": "diff_4_title",
          "type": "Text",
          "properties": {
            "text": "**Camera and Audio**"
          }
        },
        {
          "id": "diff_4_text",
          "type": "Text",
          "properties": {
            "text": "The M2 model features an upgraded 1080p FaceTime HD camera, providing a much clearer image than the 720p camera on the M1 model. It also has an improved four-speaker sound system."
          }
        },
        {
          "id": "actions_card",
          "type": "Card",
          "properties": {
            "child": "actions_col"
          }
        },
        {
          "id": "actions_col",
          "type": "Column",
          "properties": {
            "children": [
              "actions_title",
              "actions_row"
            ]
          }
        },
        {
          "id": "actions_title",
          "type": "Text",
          "properties": {
            "text": "Quick Actions",
            "style": "headline"
          }
        },
        {
          "id": "actions_row",
          "type": "Row",
          "properties": {
            "children": [
              "button_1",
              "button_2",
              "button_3"
            ],
            "spacing": "medium"
          }
        },
        {
          "id": "button_1",
          "type": "Button",
          "properties": {
            "label": "Compare Mac Models",
            "action": {
              "functionCall": {
                "call": "openUrl",
                "args": {
                  "url": "https://www.apple.com/mac/compare/"
                }
              }
            }
          }
        },
        {
          "id": "button_2",
          "type": "Button",
          "properties": {
            "label": "M2 Tech Specs",
            "action": {
              "functionCall": {
                "call": "openUrl",
                "args": {
                  "url": "https://www.apple.com/macbook-air-13-and-15-m2/specs/"
                }
              }
            }
          }
        },
        {
          "id": "button_3",
          "type": "Button",
          "properties": {
            "label": "M1 Tech Specs",
            "action": {
              "functionCall": {
                "call": "openUrl",
                "args": {
                  "url": "https://support.apple.com/kb/SP825"
                }
              }
            }
          }
        },
        {
          "id": "sources_card",
          "type": "Card",
          "properties": {
            "child": "sources_col"
          }
        },
        {
          "id": "sources_col",
          "type": "Column",
          "properties": {
            "children": [
              "sources_title",
              "sources_list"
            ]
          }
        },
        {
          "id": "sources_title",
          "type": "Text",
          "properties": {
            "text": "Sources",
            "style": "headline"
          }
        },
        {
          "id": "sources_list",
          "type": "List",
          "properties": {
            "children": [
              "source_1",
              "source_2"
            ]
          }
        },
        {
          "id": "source_1",
          "type": "Text",
          "properties": {
            "text": "https://www.apple.com/newsroom/2022/06/apple-unveils-all-new-macbook-air-supercharged-by-the-new-m2-chip/"
          }
        },
        {
          "id": "source_2",
          "type": "Text",
          "properties": {
            "text": "https://support.apple.com/kb/SP869"
          }
        }
      ]
    }
  }
]
